# Actually simpler: zero becomes 2 iff it's adjacent to a non-zero that's part of a "cluster" of non-zeros

# First, find connected components of non-zeros (using 8-way connectivity)
def find_nonzero_components(grid):
    h = len(grid)
    w = len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    def bfs(start_r, start_c):
        q = [(start_r, start_c)]
        visited[start_r][start_c] = True
        comp_cells = [(start_r, start_c)]
        while q:
            r, c = q.pop(0)
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                        if grid[nr][nc] != 0:
                            visited[nr][nc] = True
                            comp_cells.append((nr, nc))
                            q.append((nr, nc))
        return comp_cells

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                comp = bfs(r, c)
                components.append(comp)

    return components

